// TypeScript highlighting for the inspector's code panel: one <span> per line, tokens in the Code Example block's own
// classes (.mk-code-block-c comment, -s string, -k keyword) plus .dv-literal, .dv-call and .dv-type. The samples are
// generated by this demo's worker, so a tokenizer for the subset they use is enough; text goes in through
// textContent only.
const TOKEN = new RegExp(
  [
    String.raw`(\/\/.*$)`,
    String.raw`('(?:[^'\\]|\\.)*'|"(?:[^"\\]|\\.)*"|\`(?:[^\`\\]|\\.)*\`)`,
    String.raw`\b(const|let|await|async|import|export|from|new|return|for|of|if|throw|type|interface|extends|as|typeof)\b`,
    String.raw`\b(true|false|null|undefined|-?\d[\d_]*(?:\.\d+)?n?)\b`,
    String.raw`\.([A-Za-z_$][\w$]*)(?=[(<])`,
    String.raw`\b([A-Z][A-Za-z0-9]*)\b`,
  ].join('|'),
  'gm',
);
const CLASSES = [
  'mk-code-block-c',
  'mk-code-block-s',
  'mk-code-block-k',
  'dv-literal',
  'dv-call',
  'dv-type',
];

/** The lines of a TypeScript sample as highlighted <span> elements; an empty line keeps its height. */
export function codeLines(text: string): HTMLSpanElement[] {
  return text.split('\n').map((source) => {
    const line = document.createElement('span');
    let last = 0;
    for (const match of source.matchAll(TOKEN)) {
      const at = match.index ?? 0;
      if (at > last) line.append(source.slice(last, at));
      const group = match.slice(1).findIndex((part) => part !== undefined);
      const token = document.createElement('span');
      token.className = CLASSES[group] ?? '';
      if (group === 4) {
        line.append('.');
        token.textContent = match[5] ?? '';
      } else token.textContent = match[0];
      line.append(token);
      last = at + match[0].length;
    }
    line.append(source.slice(last) || (last ? '' : ' '));
    return line;
  });
}
